                    } else {
                        result.deliveries.push('duplicate:' + sub.id + ':' + item.envelope.id);
                    }
                    items.shift();
                    continue;
                }
                result.deliveries.push(sub.id + ':' + step.worker + ':' + item.envelope.id + ':' + item.attempt + ':' + step.outcome);
                if (step.outcome === 'ok') {
                    if (sub.idempotency === 'file-ledger-v1') {
                        completed.set(key, hash);
                    }
                    items.shift();
                } else if (item.attempt >= sub.maxAttempts) {
                    result.deadLetters.push(sub.id + ':' + item.envelope.id + ':attemptsExhausted');
                    items.shift();
                } else {
                    item.at = time + sub.backoffMs[item.attempt - 1];
                }
            } else {
                throw new Error('messagingScenarioStep');
            }
        } catch (error) {
            result.errors.push(error instanceof Error ? error.message : 'messagingScenarioError');
        }
    }
    return result;
}

